package cl.uss.ca.external.pure.model;

public class JournalClassificationData {
    private String uri;
    private String termEn;
    private String termEs;

    public String getUri() {
        return uri;
    }

    public void setUri(String uri) {
        this.uri = uri;
    }

    public String getTermEn() {
        return termEn;
    }

    public void setTermEn(String termEn) {
        this.termEn = termEn;
    }

    public String getTermEs() {
        return termEs;
    }

    public void setTermEs(String termEs) {
        this.termEs = termEs;
    }
}
